/* ════════ YARDIMCILAR ════════ */
function gid() { return Date.now().toString(36) + Math.random().toString(36).substr(2, 5); }
function fmtDate(ds) { return new Date(ds).toLocaleDateString("tr-TR", { day: "numeric", month: "short", year: "numeric" }); }
function fmtShort(ds) { return new Date(ds).toLocaleDateString("tr-TR", { day: "numeric", month: "short" }); }
function calcAge(bd) { if (!bd) return ""; const d = new Date(bd), now = new Date(); let a = now.getFullYear() - d.getFullYear(); if (now < new Date(now.getFullYear(), d.getMonth(), d.getDate())) a--; return a; }

